INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`) VALUES (475, 'CAPILVELT', NULL, 'Loção Capilar Capilvelt', 'Minoxidil 5%\\nD-pantenol 1%\\nVitessence qs\\nCapilvelt Pro FC 5%\\nCapilvelt Acqua 15%\\nÁgua purificada 10%\\nSérum Capilar pH 4,5 qsp 100mL', NULL, NULL, 1, '2026-03-11 08:29:31', '2026-03-16 07:49:41', 244, NULL, 0, NULL, 'un', 889820462, 'Modo de uso:  Aplicar 6 puffs no couro cabeludo (seco ou quase seco) 1 ou 2 vezes ao dia, massageando suavemente para espalhar o produto na pele do couro cabeludo. Evitar lavar os cabelos por 6 horas após a aplicação. O uso de secador, géis ou cremes capilares não interfere no efeito. Seu uso é diário e contínuo, para não perder os resultados que se iniciam dentro de 3 a 4 meses.', '2026-03-16 07:49:41');
